"""Parse simple duration strings like '1h30m' into whole seconds."""

import re

_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}

_UNIT_RE = re.compile(
    r"(\d+(?:\.\d+)?)\s*"
    r"(d(?:ays?)?|h(?:ours?)?|m(?:inutes?)?|s(?:econds?)?)",
    re.IGNORECASE,
)


def parse_duration(text):
    """Return the number of whole seconds in *text*, e.g. '1h30m' -> 5400.

    Accepts combinations of days, hours, minutes and seconds, written either
    with the short letters ('1h30m') or full unit names ('1 hour 30 minutes',
    case-insensitive), including decimal amounts like '1.5h'. Whitespace is
    allowed between components. Raises ValueError for anything else.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    total = 0.0
    pos = 0
    for match in _UNIT_RE.finditer(text):
        if text[pos:match.start()].strip():
            raise ValueError(f"invalid duration: {text!r}")
        amount, unit = match.group(1), match.group(2)
        total += float(amount) * _UNIT_SECONDS[unit[0]]
        pos = match.end()
    if pos == 0 or text[pos:].strip():
        raise ValueError(f"invalid duration: {text!r}")
    return int(total)


def format_duration(seconds):
    """Return the shortest string parse_duration accepts for *seconds*.

    e.g. 5400 -> '1h30m', 0 -> '0s'. *seconds* must be a non-negative int.
    """
    if not isinstance(seconds, int) or isinstance(seconds, bool) or seconds < 0:
        raise ValueError("seconds must be a non-negative whole number")
    if seconds == 0:
        return "0s"
    parts = []
    for unit, size in (("d", 86400), ("h", 3600), ("m", 60)):
        if size == 1:
            amount, seconds = seconds, 0
        else:
            amount, seconds = divmod(seconds, size)
        if amount:
            parts.append(f"{amount}{unit}")
    if seconds:
        parts.append(f"{seconds}s")
